26	
27	using namespace llvm;
28	using mlir::raw_indented_ostream;
29	
30	namespace {
31	class GenOpEmitsDefs {
32	public:
33	    explicit GenOpEmitsDefs(const RecordKeeper& records) : records(records) {}
34	    void run(raw_ostream& os);
35	
36	private:
37	    const RecordKeeper& records;
38	};
39	
40	void printFuncDefine(raw_indented_ostream& os, StringRef opType)
41	{
42	    os << mlir::asc::kRetType << mlir::asc::kSpaceSeparated << mlir::asc::kPrintFuncName;
43	    os << "(CodeEmitter &emitter, ";
44	    os << mlir::asc::kAscDialectNameSpace << opType << mlir::asc::kSpaceSeparated << "op) {\n";
45	}
46	
47	std::string capitalizeFirstLetter(const std::string& str)
48	{
49	    std::string capStr(str);
50	    if (!str.empty()) {
51	        capStr[0] = static_cast<char>(std::toupper(str[0]));
52	    }
53	    return capStr;
54	}
55	
56	std::string genGetterName(const std::vector<mlir::asc::VirtualArg>& args, size_t i)
57	{
58	    if (i >= args.size()) {
59	        return {};
60	    }
61	    return mlir::asc::kGetFunPrefix.str() + capitalizeFirstLetter(args[i].name);
62	}
63	
64	bool hasTrait(const Record* def, StringRef traitName)
65	{
66	    auto traits = def->getValueAsListOfDefs(mlir::asc::kTraitName);
67	    return llvm::any_of(traits, [&](const Record* trait) { return trait->getName() == traitName; });
68	}
69	
70	void indentedNewLine(raw_indented_ostream& os) { os << mlir::asc::kLineBreak << mlir::asc::kIndentationSpace; }
71	
72	void printInferOperandType(raw_indented_ostream& os, StringRef operand, const std::string& varName)
73	{
74	    os << "auto " << varName << " = op." << operand << "().getType();";
75	    indentedNewLine(os);
76	    os << R"(FAIL_OR(emitter.emitType(op.getLoc(), )" << varName << "));";
77	    indentedNewLine(os);
78	}
79	
80	void printTemplateType(raw_indented_ostream& os, StringRef operand, const std::string& varName)
81	{
82	    os << "auto " << varName << " = op." << operand << "();";
83	    indentedNewLine(os);
84	    os << R"(FAIL_OR(emitter.emitType(op.getLoc(), )" << varName << "));";
85	    indentedNewLine(os);
86	}
87	
88	void printInferElementType(raw_indented_ostream& os, StringRef operand, StringRef typeName, StringRef elementName)
89	{
90	    os << "  auto " << typeName << " = op." << operand << "().getType();";
91	    indentedNewLine(os);
92	    os << "auto " << elementName << " = " << typeName << ".getElementType();";
93	    indentedNewLine(os);
94	    os << R"(FAIL_OR(emitter.emitType(op.getLoc(),)" << elementName << R"());)";
95	    indentedNewLine(os);
96	}
97	
98	void printInferEnumType(raw_indented_ostream& os, StringRef operand, StringRef attrType, const std::string& typeName)
99	{
100	    os << "  auto " << typeName << "= op." << operand << "();";
101	    indentedNewLine(os);
102	    os << R"(os << ascNamespace << ")" << attrType << R"(::")";
103	    os << R"( << ascendc::stringifyEnum()" << typeName << R"().upper();)";
104	    indentedNewLine(os);
105	}
106	
107	void printFuncOutputDeclaration(raw_indented_ostream& os)
108	{
109	    os << R"(  auto resNum = op.getOperation()->getNumResults();
110	  auto& os = emitter.ostream();
111	  if (resNum == 1) {
112	    FAIL_OR(emitter.emitVariableDeclaration(op->getResult(0), false));
113	    os << " = ";
114	  })";
115	    indentedNewLine(os);
116	}
117	
118	void printOperand(raw_indented_ostream& os, StringRef operand, const mlir::asc::VirtualArg& arg)
119	{
120	    if (arg.optional) {
121	        os << "EXEC_IF_TRUE(op." << operand << "(), ";
122	        os << R"(os << ", " << emitter.getOrCreateName(op.)" << operand << R"(());)";
123	        os << ")";
124	    } else {
125	        os << R"(os << emitter.getOrCreateName(op.)" << operand << R"(());)";
126	    }
127	    indentedNewLine(os);
128	}
129	
130	void printOperandValue(raw_indented_ostream& os, StringRef operand)
131	{
132	    os << R"(os << emitter.getOrCreateName(op.)" << operand << "());";
133	    indentedNewLine(os);
134	}
135	
136	void printPointerOperandValue(raw_indented_ostream& os, StringRef operand)
137	{
138	    os << "os << \"&\" << emitter.getOrCreateName(op." << operand << "());";
139	    indentedNewLine(os);
140	}
141	
142	void printPointerToIntOperandValue(raw_indented_ostream& os, StringRef operand)
143	{
144	    os << "os << \"reinterpret_cast<uint64_t>(\" << emitter.getOrCreateName(op." << operand << "()) << \")\";";
145	    indentedNewLine(os);
146	}
147	
148	bool hasTemplateParams(const std::vector<int64_t>& paramTypes)
149	{
150	    return std::any_of(
151	        paramTypes.cbegin(), paramTypes.cend(), [](const auto& type) { return type > mlir::asc::kNormalType; });
152	}
153	
154	void printTemplateCallStart(raw_indented_ostream& os, const std::vector<int64_t>& paramTypes, bool isMemberFunc)
155	{
156	    if (isMemberFunc) {
157	        if (paramTypes[0] != mlir::asc::kNormalType) {
158	            os << mlir::asc::kOutTemplate;
159	            indentedNewLine(os);
160	        }
161	        os << mlir::asc::kOutFuncName << mlir::asc::kOutTemplateCallStart;
162	        indentedNewLine(os);
163	    } else {
164	        os << mlir::asc::kOutAscNamespace << mlir::asc::kOutFuncName << mlir::asc::kOutTemplateCallStart;
165	        indentedNewLine(os);
166	    }
167	}
168	
169	bool printTemplateParam(
170	    raw_indented_ostream& os, const Record* def, const std::vector<int64_t>& paramTypes,
171	    const std::vector<mlir::asc::VirtualArg>& args, bool isMemberFunc = false)
172	{
173	    if (!hasTemplateParams(paramTypes)) {
174	        return false;
175	    }
176	    printTemplateCallStart(os, paramTypes, isMemberFunc);
177	    bool first = true;
178	    for (size_t i = 0; i < paramTypes.size(); ++i) {
179	        if (paramTypes[i] <= mlir::asc::kNormalType) {
180	            continue;
181	        }
182	        if (!first) {
183	            os << mlir::asc::kOutSeparate;
184	            indentedNewLine(os);
185	        }
186	        first = false;
187	        std::string templateTypeVar = "templateType" + std::to_string(i);
188	        std::string elementTypeVar = "elType" + std::to_string(i);
189	        std::string attrTypeVar = "iAttr" + std::to_string(i);
190	        switch (paramTypes[i]) {
191	            case mlir::asc::kInferType: // infer operand type
192	                printInferOperandType(os, genGetterName(args, i), templateTypeVar);
193	                break;
194	            // infer operand element type, such as get T form LocalTensor<T>
195	            case mlir::asc::kInferElementType:
196	                printInferElementType(os, genGetterName(args, i), templateTypeVar, elementTypeVar);
197	                break;
198	            case mlir::asc::kInferEnumType: // pass by attr
199	                printInferEnumType(
200	                    os, genGetterName(args, i),
201	                    mlir::asc::removeAscDialectNameSpace(args[i].cppType, def->getValueAsString("cppNamespace")),
202	                    attrTypeVar);
203	                break;
204	            case mlir::asc::kInferValue: // pass by value
205	                printOperandValue(os, genGetterName(args, i));
206	                break;
207	            case mlir::asc::kTemplateType:  // pass by template type
208	            case mlir::asc::kInferTypeAttr: // type attribute, use directly as template type
209	                printTemplateType(os, genGetterName(args, i), templateTypeVar);
210	                break;
211	        }
212	    }
213	    os << mlir::asc::kOutTemplateCallEnd;
214	    indentedNewLine(os);
215	    return true;
216	}
217	
218	void printFunctionParam(
219	    raw_indented_ostream& os, const Record* def, const std::vector<int64_t>& paramTypes,
220	    const std::vector<mlir::asc::VirtualArg>& args, bool hasTemplate = false, bool isMemberFunc = false)
221	{
222	    size_t i = isMemberFunc ? 1 : 0;
223	    if (!hasTemplate) {
224	        if (!isMemberFunc)
225	            os << mlir::asc::kOutAscNamespace;
226	        os << mlir::asc::kOutFuncName << mlir::asc::kOutFuncCallStart;
227	        indentedNewLine(os);
228	    } else {
229	        os << mlir::asc::kOutFuncCallStart;
230	        indentedNewLine(os);
231	    }
232	    bool first = true;
233	    for (; i < paramTypes.size(); ++i) {
234	        if (paramTypes[i] > mlir::asc::kInferElementType) {
235	            continue;
236	        }
237	        if (!first && !args[i].optional) {
238	            os << mlir::asc::kOutSeparate;
239	            indentedNewLine(os);
240	        }
241	        first = false;
242	        std::string operandVar = "var" + std::to_string(i);
243	        if (paramTypes[i] == -1) { // -1 means attr argument
244	            printInferEnumType(
245	                os, genGetterName(args, i),
246	                mlir::asc::removeAscDialectNameSpace(args[i].cppType, def->getValueAsString("cppNamespace")),
247	                operandVar);
248	        } else if (paramTypes[i] == mlir::asc::kPointerValue) {
249	            printPointerOperandValue(os, genGetterName(args, i));
250	        } else if (paramTypes[i] == mlir::asc::kPointerToIntValue) {
251	            printPointerToIntOperandValue(os, genGetterName(args, i));
252	        } else {
253	            printOperand(os, genGetterName(args, i), args[i]);
254	        }
255	    }
256	    os << "os << \")\";";
257	    indentedNewLine(os);
258	    os << R"(return success();)"
259	       << "\n}\n";
260	}
261	
262	void printOp(raw_indented_ostream& os, const Record* def)
263	{
264	    const auto opTypeFullName = def->getName();
265	    const auto opType = mlir::asc::removeDialectPrefix(opTypeFullName, "AscendC");
266	    auto templatePos = def->getValueAsListOfInts("paramTypeLists");
267	    std::vector<mlir::asc::VirtualArg> args;
268	    mlir::asc::fetchArguments(def->getValueAsDag("arguments"), args);
269	    bool isMemberFunc = hasTrait(def, "AscMemberFunc");
270	    printFuncDefine(os, opType);
271	    if (!templatePos.empty()) {
272	        printFuncOutputDeclaration(os);
273	        if (isMemberFunc) {
274	            os << R"(os << emitter.getOrCreateName(op.)" << genGetterName(args, 0) << R"(()) << ".";)";
275	            indentedNewLine(os);
276	        }
277	        bool hasTemplate = printTemplateParam(os, def, templatePos, args, isMemberFunc);
278	        printFunctionParam(os, def, templatePos, args, hasTemplate, isMemberFunc);
279	    } else {
280	        os << mlir::asc::kIndentationSpace << "return autoPrintOp<ascendc::" << opType << ">(emitter, op);\n}\n";
281	    }
282	}
283	
284	void GenOpEmitsDefs::run(raw_ostream& os)
285	{
286	    raw_indented_ostream ios(os);
287	    for (const auto* def : records.getAllDerivedDefinitions("Op")) {
288	        if (!def->getValueAsBit(mlir::asc::kAutoEmitAttr)) {
289	            continue;
290	        }
291	        printOp(ios, def);
292	    }
293	}
294	
295	TableGen::Emitter::OptClass<GenOpEmitsDefs> registration(
296	    "gen-opemit-defs", "Generate op emit methods from MLIR operation defs");
297	
298	} // namespace
299

