27	void fetchResults(const DagInit* resultsDag, std::vector<VirtualArg>& dest)
28	{
29	    const auto* outsOp = dyn_cast<DefInit>(resultsDag->getOperator());
30	    assert(outsOp && outsOp->getDef()->getName() == "outs");
31	    for (unsigned i = 0, e = resultsDag->getNumArgs(); i < e; ++i) {
32	        VirtualArg result;
33	        auto name = resultsDag->getArgNameStr(i);
34	        if (name.empty()) {
35	            result.name = "arg" + std::to_string(i);
36	        } else {
37	            result.name = name;
38	        }
39	        result.substitution = result.name;
40	        const auto* init = dyn_cast<DefInit>(resultsDag->getArg(i));
41	        assert(init && "argument must have defined types");
42	        const auto* resultDef = init->getDef();
43	        if (resultDef->isSubClassOf("Variadic")) {
44	            result.cppType = "::std::vector< ::mlir::Type >";
45	        } else {
46	            result.cppType = "::mlir::Type";
47	        }
48	        dest.push_back(result);
49	    }
50	}
