52	void fetchArguments(const DagInit* argsDag, std::vector<VirtualArg>& dest)
53	{
54	    const auto* insOp = dyn_cast<DefInit>(argsDag->getOperator());
55	    assert(insOp && insOp->getDef()->getName() == "ins");
56	    for (unsigned i = 0, e = argsDag->getNumArgs(); i < e; ++i) {
57	        VirtualArg arg;
58	        auto name = argsDag->getArgNameStr(i);
59	        if (name.empty()) {
60	            arg.name = "arg" + std::to_string(i);
61	        } else {
62	            arg.name = name;
63	        }
64	        arg.substitution = arg.name;
65	        const auto* init = dyn_cast<DefInit>(argsDag->getArg(i));
66	        assert(init && "argument must have defined types");
67	        const auto* argDef = init->getDef();
68	        if (argDef->isSubClassOf("TypeConstraint")) {
69	            if (argDef->isSubClassOf("Variadic")) {
70	                arg.cppType = "::std::vector< ::mlir::Value >";
71	            } else {
72	                arg.cppType = "::mlir::Value";
73	            }
74	            if (argDef->isSubClassOf("Optional")) {
75	                arg.optional = true;
76	                std::stringstream str;
77	                str << arg.name << ".value_or(" << arg.cppType << "{})";
78	                arg.substitution = str.str();
79	                arg.cppType = "::std::optional< " + arg.cppType + " >";
80	                arg.defaultValue = "py::none()";
81	            }
82	        } else if (argDef->isSubClassOf("AttrConstraint")) {
83	            arg.cppType = argDef->getValueAsString("returnType");
84	            if (argDef->getName() == "UnitAttr") {
85	                arg.optional = true;
86	                arg.substitution = arg.name;
87	                arg.defaultValue = "false";
88	            } else if (argDef->isSubClassOf("OptionalAttr")) {
89	                arg.optional = true;
90	                std::stringstream str;
91	                str << arg.name << ".value_or(" << argDef->getValueAsString("storageType").str() << "{})";
92	                arg.substitution = str.str();
93	                arg.defaultValue = "py::none()";
94	            }
95	        }
96	        dest.push_back(arg);
97	    }
98	}
99	
100	StringRef removeDialectPrefix(StringRef fullName, StringRef dialectName)
101	{
102	    std::string prefix = (dialectName + "_").str();
103	    if (fullName.starts_with(prefix)) {
104	        return fullName.substr(dialectName.size() + 1);
105	    }
106	    return fullName;
107	}
108	
109	StringRef removeAscDialectNameSpace(StringRef fullName, StringRef ascCppNamespace)
110	{
111	    std::string prefix = ascCppNamespace.str();
112	    if (fullName.starts_with(prefix)) {
113	        return fullName.substr(ascCppNamespace.size());
114	    }
115	    return fullName;
116	}
