  let description = "`AscendC::" # apiName # "` is a vector binary operation (L1 API).\n";
  let arguments = (ins AnyType:$dst, AnyType:$src0, AnyType:$src1,
                   Variadic<UI64>:$mask, AnyType:$repeatTimes, 
